// Port of hardware/display.py's render(): the browser preview draws the exact 128x64 frame the
// glasses receive. frontend/src/lib/oled.test.ts compares against frames generated by Python.
import assets from "../../../hardware/oled-assets.json";

export const WIDTH = 128;
export const HEIGHT = 64;
export interface Cue {
  icon_id: string | null;
  label: string;
  effective_tier: number;
  remaining_ms: number;
  direction?: string | null;
  bearing_degrees?: number | null;
}
const font: Record<string, string[]> = Object.fromEntries(
  Object.entries(assets.glyphs).map(([char, rows]) => [char, rows.split(" ")]),
);
const bitmaps = assets.bitmaps as Record<string, string[]>;
const ICON_SIZE = 32;

export class Bitmap {
  buffer = new Uint8Array((WIDTH * HEIGHT) / 8);
  pixel(x: number, y: number, value = 1) {
    if (x < 0 || x >= WIDTH || y < 0 || y >= HEIGHT) return;
    const index = y * (WIDTH / 8) + (x >> 3);
    const bit = 1 << (7 - (x % 8));
    if (value) this.buffer[index] |= bit;
    else this.buffer[index] &= 255 ^ bit;
  }
  get(x: number, y: number) {
    return (this.buffer[y * (WIDTH / 8) + (x >> 3)] >> (7 - (x % 8))) & 1;
  }
  line(x0: number, y0: number, x1: number, y1: number, value = 1) {
    const dx = Math.abs(x1 - x0);
    const sx = x0 < x1 ? 1 : -1;
    const dy = -Math.abs(y1 - y0);
    const sy = y0 < y1 ? 1 : -1;
    let error = dx + dy;
    for (;;) {
      this.pixel(x0, y0, value);
      if (x0 === x1 && y0 === y1) return;
      const twice = 2 * error;
      if (twice >= dy) {
        error += dy;
        x0 += sx;
      }
      if (twice <= dx) {
        error += dx;
        y0 += sy;
      }
    }
  }
  rect(x: number, y: number, width: number, height: number, fill = false) {
    if (fill) {
      for (let row = y; row < y + height; row++)
        this.line(x, row, x + width - 1, row);
      return;
    }
    this.line(x, y, x + width - 1, y);
    this.line(x, y + height - 1, x + width - 1, y + height - 1);
    this.line(x, y, x, y + height - 1);
    this.line(x + width - 1, y, x + width - 1, y + height - 1);
  }
  text(text: string, x: number, y: number, value = 1) {
    for (const char of text.toUpperCase()) {
      (font[char] ?? font["?"]).forEach((pixels, row) => {
        [...pixels].forEach((pixel, column) => {
          if (pixel === "1") this.pixel(x + column, y + row, value);
        });
      });
      x += 6;
    }
  }
  centered(text: string, y: number, value = 1) {
    this.text(
      text,
      Math.floor((WIDTH - ([...text].length * 6 - 1)) / 2),
      y,
      value,
    );
  }
}

function drawIcon(bitmap: Bitmap, id: string, x: number, y: number) {
  (bitmaps[id] ?? []).forEach((bits, row) => {
    for (let column = 0; column < bits.length; column++)
      if (bits[column] === "1") bitmap.pixel(x + column, y + row);
  });
}

export function fitLabel(label: string, width: number) {
  const text = label.toUpperCase().split(/\s+/).filter(Boolean).join(" ");
  const chars = [...text];
  return chars.length <= width
    ? text
    : chars
        .slice(0, width - 3)
        .join("")
        .trimEnd() + "...";
}

// Icon top-left per placement and its label row (always reserved, so the icon never moves).
export function layout(
  _direction: string | null | undefined,
  label: string | null,
) {
  const x = (WIDTH - ICON_SIZE) / 2,
    y = 10,
    textY = 55;
  const text = label ? fitLabel(label, 19) : null;
  const tw = text ? [...text].length * 6 - 1 : 0;
  return {
    box: [x, y, ICON_SIZE, ICON_SIZE] as const,
    icon: [x, y] as const,
    text,
    origin: [Math.floor((WIDTH - tw) / 2), textY] as const,
    width: tw,
  };
}

function drawEdge(bitmap: Bitmap, direction?: string | null) {
  // Solid triangle beside the stationary icon, pointing toward the sound (see hardware/display.py).
  if (direction === "left" || direction === "right") {
    for (let k = -6; k <= 6; k++)
      for (let x = 30 + Math.abs(k); x < 37; x++)
        bitmap.pixel(direction === "left" ? x : WIDTH - 1 - x, 26 + k);
  } else if (direction === "front") {
    for (let row = 0; row < 6; row++) for (let x = 64 - row; x < 65 + row; x++) bitmap.pixel(x, row);
  } else if (direction === "behind") {
    for (let row = 0; row < 6; row++) for (let x = 64 - row; x < 65 + row; x++) bitmap.pixel(x, 53 - row);
  }
}

// Tier changes only the box around the cue; direction appears as a compass arrow around the centered icon.
export function render(cue: Cue | null, showLabels = true): Bitmap {
  const bitmap = new Bitmap();
  if (
    !cue ||
    cue.effective_tier === 0 ||
    cue.remaining_ms === 0 ||
    !cue.icon_id
  )
    return bitmap;
  const tier = cue.effective_tier;
  const place = layout(
    cue.direction,
    showLabels || tier === 4 ? cue.label : null,
  );
  const [x, y, cw, ch] = place.box;
  if (tier >= 2) bitmap.rect(x - 2, y - 2, cw + 4, ch + 4);
  if (tier >= 3) bitmap.rect(x - 4, y - 4, cw + 8, ch + 8);
  drawIcon(bitmap, cue.icon_id, place.icon[0], place.icon[1]);
  if (place.text) {
    const [tx, ty] = place.origin;
    if (tier === 4) bitmap.rect(tx - 2, ty - 2, place.width + 4, 11, true);
    bitmap.text(place.text, tx, ty, tier === 4 ? 0 : 1);
  }
  if (cue.direction && cue.bearing_degrees != null && Number.isFinite(cue.bearing_degrees)) {
    const bucket = Math.floor((((cue.bearing_degrees % 360) + 360) % 360 + 11.25) / 22.5) % 16;
    for (const [x, y] of assets.direction_arrows[bucket]) bitmap.pixel(x, y);
  } else drawEdge(bitmap, cue.direction);
  return bitmap;
}

export const hex = (bitmap: Bitmap) =>
  Array.from(bitmap.buffer, (b) => b.toString(16).padStart(2, "0")).join(""); // taste-skill-ignore: hex bytes
